IMG_ROC    = ""
IMG_CAL    = ""
IMG_DCA    = ""
IMG_RADAR  = ""
IMG_DELONG = ""
IMG_S1     = ""
IMG_S2     = ""

def safe_show_df(df):
    import warnings
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        try:
            st.dataframe(df, width="stretch")
        except Exception:
            try:
                st.dataframe(df, use_container_width=True)
            except Exception:
                st.dataframe(df)

st.title(L["title"])
st.caption(L["caption"])

tabs = st.tabs([L["tab_pred"], L["tab_eval"], L["tab_delong"], L["tab_shap"]])

with tabs[0]:
    st.subheader(L["input_sec"])
    user_inputs = {}
    col1, col2 = st.columns(2)
    feat_keys = list(FEATURE_META.keys())
    for i, f_name in enumerate(feat_keys):
        meta = FEATURE_META[f_name]
        step = (meta["max"] - meta["min"]) / 100.0 if meta["max"] != meta["min"] else 0.1
        target_col = col1 if i % 2 == 0 else col2
        user_inputs[f_name] = target_col.number_input(
            f_name,
            min_value=float(meta["min"]),
            max_value=float(meta["max"]),
            value=float(meta["default"]),
            step=round(step, 4)
        )

    st.divider()
    if st.button(L["btn_calc"], type="primary"):
        input_df = pd.DataFrame([user_inputs])
        
        import warnings
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            # 传递 numpy array 消除 sklearn 特征名称 warning
            scaled_x = scaler.transform(input_df.values)
            prob = model.predict_proba(scaled_x)[0][1]

        st.subheader(L["res_sec"])
        r1, r2 = st.columns(2)
        r1.metric(L["metric_prob"], f"{prob * 100:.2f} %")
        with r2:
            if prob >= 0.5:
                st.error(L["risk_high"])
            else:
                st.success(L["risk_low"])
        st.progress(float(prob))

with tabs[1]:
    st.subheader(L["table_tr"])
    safe_show_df(pd.DataFrame(METRICS_TRAIN).T)

    if len(METRICS_TEST) > 0:
        st.subheader(L["table_te"])
        safe_show_df(pd.DataFrame(METRICS_TEST).T)

    st.divider()
    c_roc, c_cal = st.columns(2)
    with c_roc:
        st.markdown(f"**{L['roc_title']}**")
        st.image(base64.b64decode(IMG_ROC))
    with c_cal:
        st.markdown(f"**{L['cal_title']}**")
        st.image(base64.b64decode(IMG_CAL))

    c_dca, c_rad = st.columns(2)
    with c_dca:
        st.markdown(f"**{L['dca_title']}**")
        st.image(base64.b64decode(IMG_DCA))
    with c_rad:
        st.markdown(f"**{L['radar_title']}**")
        st.image(base64.b64decode(IMG_RADAR))

with tabs[2]:
    st.subheader(L["delong_title"])
    m_names = DELONG_DATA["models"]
    
    if DELONG_DATA["test"] is not None:
        st.markdown("**测试集 DeLong P 值矩阵表 (Test Set Matrix)**")
        df_d_te = pd.DataFrame(DELONG_DATA["test"], index=m_names, columns=m_names)
        safe_show_df(df_d_te.style.format("{:.4f}"))
        
    st.markdown("**训练集 DeLong P 值矩阵表 (Train Set Matrix)**")
    df_d_tr = pd.DataFrame(DELONG_DATA["train"], index=m_names, columns=m_names)
    safe_show_df(df_d_tr.style.format("{:.4f}"))
    
    st.image(base64.b64decode(IMG_DELONG))

